package br.com.poolcontrol.financeiro.api;
import br.com.poolcontrol.financeiro.domain.*; import br.com.poolcontrol.financeiro.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/financeiro/planejamento") @RequiredArgsConstructor public class PlanningController { private final BudgetRepository budgets; private final BudgetItemRepository items; private final FinancialRecurrenceRepository recurrences;
 @GetMapping("/orcamentos") List<Budget> budgets(){return budgets.findAll();} @PostMapping("/orcamentos") Budget budget(@RequestBody Budget b){return budgets.save(b);} @GetMapping("/orcamentos/{id}/itens") List<BudgetItem> items(@PathVariable UUID id){return items.findAll().stream().filter(i->id.equals(i.getOrcamentoId())).toList();} @PostMapping("/orcamentos/{id}/itens") BudgetItem item(@PathVariable UUID id,@RequestBody BudgetItem i){i.setOrcamentoId(id); return items.save(i);} @GetMapping("/recorrencias") List<FinancialRecurrence> recurrence(){return recurrences.findAll();} @PostMapping("/recorrencias") FinancialRecurrence recurrence(@RequestBody FinancialRecurrence r){return recurrences.save(r);} }
